-- Hero class (class ID 10) for Turoran Classless. GENERATED by apps/hero/gen_hero.py; edit the generator.
-- Server side only: the client needs the matching patch-n DBCs (V023__HeroClass.sql + gen_hero.py --client-dbc).
-- Idempotent: safe to re-run.

-- ChrClasses.dbc override row (server). DisplayPower 0 = POWER_MANA (gauntlet-design.md section 12);
-- mod-classless OnPlayerHasActivePowerType() keeps rage/energy/runic/focus active for all classes.
DELETE FROM `chrclasses_dbc` WHERE `ID` = 10;

-- CharStartOutfit.dbc override rows (server gives these items at creation).
DELETE FROM `charstartoutfit_dbc` WHERE `ClassID` = 10;

-- Base stats: per-stat mean of the 9 non-DK classes, scaled to the Paladin/Druid average total.
-- BaseHP/BaseMana follow the classless convention (Warrior HP, Mage mana for every class).
DELETE FROM `player_class_stats` WHERE `Class` = 10;

-- Combat/regen tables: class 10 rows = mean of Paladin and Druid (the stock rows for slot 10 are placeholders),
-- except gtregenmpperspt_dbc = 2.0 x the highest mana-class coefficient (Hero mana regen).
DELETE FROM `gtchancetomeleecrit_dbc` WHERE `ID` BETWEEN 900 AND 999;
DELETE FROM `gtchancetospellcrit_dbc` WHERE `ID` BETWEEN 900 AND 999;
DELETE FROM `gtoctregenhp_dbc` WHERE `ID` BETWEEN 900 AND 999;
DELETE FROM `gtregenhpperspt_dbc` WHERE `ID` BETWEEN 900 AND 999;
DELETE FROM `gtregenmpperspt_dbc` WHERE `ID` BETWEEN 900 AND 999;
DELETE FROM `gtchancetomeleecritbase_dbc` WHERE `ID` = 9;
DELETE FROM `gtchancetospellcritbase_dbc` WHERE `ID` = 9;
DELETE FROM `gtoctclasscombatratingscalar_dbc` WHERE `ID` BETWEEN 289 AND 320;

-- Creation: every playable race, starting at the race's Warrior start (Blood Elf: Paladin start).
DELETE FROM `playercreateinfo` WHERE `class` = 10;
DELETE FROM `playercreateinfo_action` WHERE `class` = 10;

